import { createElement, useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';

import { CalendarClock } from '@hexa-ui/icons';
import { featureToggles } from 'config/featureToggle';
import { PAGES_WITH_DATA } from 'constants/dataRefresh/dataRefreshConfig';
import { useDataRefreshContext } from 'contexts';
import { useCurrentPage, useMultiplesFeatureToggles } from 'hooks';
import {
  useSidebarActive,
  useSidebarExtraUtils,
} from 'martech-portal-shared-services';

const renderRefreshSourceIcon = () => createElement(CalendarClock);

export const OwrSidebarBridge = () => {
  const { formatMessage } = useIntl();
  const { currentPage } = useCurrentPage();
  const { setModalOpen } = useDataRefreshContext();
  const refreshSourceToggleId = featureToggles.pillar.refreshSource.id;
  const {
    featuresListByToggleName: sidebarToggles,
    togglesReady: sidebarTogglesReady,
  } = useMultiplesFeatureToggles([refreshSourceToggleId]);

  const onRefreshSourceClick = useCallback(() => {
    setModalOpen(true);
  }, [setModalOpen]);

  const extraUtils = useMemo(() => {
    if (!sidebarTogglesReady || !sidebarToggles[refreshSourceToggleId]) {
      return [];
    }

    const pageHasData =
      !!currentPage &&
      (PAGES_WITH_DATA as readonly string[]).includes(currentPage);

    if (!pageHasData) {
      return [];
    }

    return [
      {
        id: refreshSourceToggleId,
        title: formatMessage({ id: 'Sidebar.refreshAndSource' }),
        icon: renderRefreshSourceIcon,
        onPageChange: onRefreshSourceClick,
      },
    ];
  }, [
    currentPage,
    formatMessage,
    onRefreshSourceClick,
    sidebarToggles,
    sidebarTogglesReady,
    refreshSourceToggleId,
  ]);

  useSidebarActive(true);
  useSidebarExtraUtils(extraUtils);

  return null;
};
